// Checks the progression item assets that the server ships
// (backend/public/progression/items/, generated by
// docs/progression/svg/generate_assets.py) against the rules of
// docs/progression/CONTRACT.md §10: every SVG compiles strictly with the same
// options as flutter_svg's runtime loader, uses its template's viewBox, has
// no filter / mask / text / pattern, and prefixes its internal ids with the
// item id; textures are 1200 × 600 rasters under 150 KB.
//
// With PROGRESSION_ASSETS_RENDER_DIR=<dir>, each SVG is also rendered by
// flutter_svg into <dir>/<id>.png (to compare with the Chrome contact sheets).
import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/widgets.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:vector_graphics_compiler/vector_graphics_compiler.dart';

final _dir = Directory('../backend/public/progression/items');

const _viewBoxes = {
  'avatar': ['0 0 120 120', '0 -6 120 126'],
  'frame': ['0 0 240 150'],
  'flight': ['0 0 150 150'],
  'badge': ['0 0 120 120'],
};

final _forbidden = RegExp(r'<\s*(filter|mask|text|pattern|style|image|foreignObject)\b|patternTransform');

List<File> _files(String ext) {
  if (!_dir.existsSync()) return const [];
  return _dir.listSync().whereType<File>().where((f) => f.path.endsWith('.$ext')).toList()
    ..sort((a, b) => a.path.compareTo(b.path));
}

String _id(File f) {
  final name = f.uri.pathSegments.last;
  return name.substring(0, name.lastIndexOf('.'));
}

/// Same options as flutter_svg's runtime loader (no PathOps optimizers).
List<int> _compile(String xml, String name) => encodeSvg(
      xml: xml,
      debugName: name,
      enableClippingOptimizer: false,
      enableMaskingOptimizer: false,
      enableOverdrawOptimizer: false,
      warningsAsErrors: true,
    );

void main() {
  final svgs = _files('svg');
  final rasters = [..._files('webp'), ..._files('png')];

  test('the asset folder is there and holds the generated files', () {
    expect(_dir.existsSync(), isTrue, reason: 'run docs/progression/svg/generate_assets.py');
    expect(svgs.length, greaterThanOrEqualTo(100));
    expect(rasters.length, greaterThanOrEqualTo(20));
  });

  for (final file in svgs) {
    final id = _id(file);
    test('$id.svg follows the flutter_svg rules', () {
      final xml = file.readAsStringSync();
      final type = id.split('.').first;

      final viewBox = RegExp(r'<svg[^>]*\sviewBox="([^"]+)"').firstMatch(xml)?.group(1);
      expect(_viewBoxes[type], isNotNull, reason: 'unknown item type "$type"');
      expect(_viewBoxes[type], contains(viewBox));

      expect(_forbidden.hasMatch(xml), isFalse, reason: 'filter, mask, text or pattern found');

      final prefix = '${id.replaceAll('.', '-')}-';
      for (final m in RegExp(r'\sid="([^"]+)"').allMatches(xml)) {
        expect(m.group(1), startsWith(prefix));
      }
      for (final m in RegExp(r'url\(#([^)]+)\)').allMatches(xml)) {
        expect(xml, contains('id="${m.group(1)}"'), reason: 'dangling reference #${m.group(1)}');
      }

      expect(_compile(xml, id), isNotEmpty);
    });
  }

  for (final file in rasters) {
    final id = _id(file);
    test('$id raster texture is 1200 × 600 and under 150 KB', () async {
      final bytes = file.readAsBytesSync();
      expect(bytes.length, lessThan(150 * 1024));
      final codec = await ui.instantiateImageCodec(bytes);
      final frame = await codec.getNextFrame();
      expect(frame.image.width, 1200);
      expect(frame.image.height, 600);
      frame.image.dispose();
      codec.dispose();
    });
  }

  final renderDir = Platform.environment['PROGRESSION_ASSETS_RENDER_DIR'];
  if (renderDir != null && renderDir.isNotEmpty) {
    testWidgets('renders every SVG with flutter_svg into $renderDir', (tester) async {
      await tester.runAsync(() async {
        final out = Directory(renderDir)..createSync(recursive: true);
        for (final file in svgs) {
          final info = await vg.loadPicture(SvgStringLoader(file.readAsStringSync()), null);
          const scale = 2.0;
          final w = (info.size.width * scale).round();
          final h = (info.size.height * scale).round();
          final recorder = ui.PictureRecorder();
          final canvas = Canvas(recorder)..scale(scale);
          canvas.drawPicture(info.picture);
          final image = await recorder.endRecording().toImage(w, h);
          final png = await image.toByteData(format: ui.ImageByteFormat.png);
          File('${out.path}/${_id(file)}.png').writeAsBytesSync(png!.buffer.asUint8List());
          image.dispose();
          info.picture.dispose();
        }
      });
    });
  }
}
